		public void ChangeAnimStatePoke(global::BattlePokemonEntity.AnimationState state, float duration = 0.15f, float startTime = 0f) {
			if (!IsEnable)
				return;

			_lastPlayAnimationState = state;

			if (state != BattlePokemonEntity.AnimationState.WaitA01 && state != BattlePokemonEntity.AnimationState.Max)
				_isSickSpeedSuspend = true;

			if (state != BattlePokemonEntity.AnimationState.Max)
			{
				Entity.RequestAnimationState(state, duration, startTime);
				_entity.GetAnimationPlayer().SetAnimSpeed(1.0f);
			}

			UpdateAnimSpeed();
		}
		protected override void UpdateAnimSpeed() {
			if (!IsEnable)
				return;

			float speed = _animSpeed;
			if (Entity.GetModelEntityType() != BattleObjectEntity.ModelEntityType.Contest)
			{
				if (!BattleViewCore.isInstantiated)
					return;

				var viewSystem = BattleViewCore.Instance.ViewSystem;
				if (viewSystem == null)
					return;

				var bpp = viewSystem.GetBattlePokeParam(m_vPos);
				if (bpp == null)
					return;

				var sick = bpp.GetPokeSick();
				if (!Mathf.Approximately(speed, 0.0f) && Entity.CurrentAnimationState == BattlePokemonEntity.AnimationState.WaitA01 && viewSystem.GetHUD() != null)
				{
					bool isPinch = viewSystem.GetHUD().HUD_IsPinch(m_vPos);
					if ((sick == Sick.NONE && !isPinch) || _isSickSpeedSuspend)
					{
						if (_param.GetMonsNo() != MonsNo.GOOSU)
							Entity.PokemonCustomNodeAnim.isAutoUpdate = true;

						if (!Entity.GetAnimationPlayer().IsPlaying)
							Entity.GetAnimationPlayer().Resume();

						_isSickSpeedSuspend = false;
					}
					else
					{
						bool isPlaying = Entity.GetAnimationPlayer().IsPlaying;
						if (sick == Sick.KOORI)
						{
							if (isPlaying)
								Entity.GetAnimationPlayer().Stop();

							speed = ANIM_SPEED_STATUS_ABNORMALITY_KOORI;
							if (_param.GetMonsNo() != MonsNo.GOOSU)
								Entity.PokemonCustomNodeAnim.isAutoUpdate = false;
						}
						else
						{
							if (!isPlaying)
								Entity.GetAnimationPlayer().Resume();

							speed = ANIM_SPEED_STATUS_ABNORMALITY;
							if (_param.GetMonsNo() != MonsNo.GOOSU)
								Entity.PokemonCustomNodeAnim.isAutoUpdate = true;
						}
					}
				}

				var blinkParam = BattleObjectEntity.CharaAutomaticBlinkProcess.BlinkIntParameter.Default;
				if (sick == Sick.NEMURI && !m_disableSleepEye)
					blinkParam = BattleObjectEntity.CharaAutomaticBlinkProcess.BlinkIntParameter.Sleep;

				Entity.SetBlinkIntParameter(blinkParam);
				Entity.SetBlinkEnabled(speed > 0.0f && Entity.CurrentAnimationState != BattlePokemonEntity.AnimationState.Down);
			}

			Entity.SetAnimationSpeed(speed);
		}
