				{
					if (simpleParam.gType != poketool.PokeGType.NORMAL && simpleParam.gType != poketool.PokeGType.SPECIAL)
					{
						if (voiceType == VOICE_TYPE.VOICE_TYPE_DOWN)
							voiceName = "05";

						switchNo = 2;
					}

					param.isSetSwitch = true;
				}
				else if (monsNo == MonsNo.PIKATYUU)
				{
					if (simpleParam.gType != poketool.PokeGType.NORMAL && simpleParam.gType != poketool.PokeGType.SPECIAL)
					{
						if (voiceType == VOICE_TYPE.VOICE_TYPE_DOWN)
							voiceName = "06";

						switchNo = formNo == 0 ? 2 : 4;
					}

					param.isSetSwitch = true;
				}
			}

			param.PostEventName = string.Format("Play_PV_Btl_{0:d3}_{1:d2}_{2}", (int)monsNo, formNo, voiceName);
			param.SwitchGroup = string.Format("PM{0:d3}VC", (int)monsNo);
			param.SwitchName = string.Format("PM{0:d3}_{1:d2}", (int)monsNo, switchNo);
			return param;
		}
