		public void SetVisibleDigudaStone(bool value) {
			if (!IsEnable)
				return;

			if (Entity.LandingType != LandingType.GROUND)
				return;

			if (_iPtrDigudaStone == null && value)
				CreateDigudaStone();

			IsVisibleDigudaStone = value;
			UpdateVisible();
		}
		private void CreateDigudaStone() {
			string fileName = "digda_rock";
			var cachedModel = BattleViewAssetManager.CachedModelData.Find(x => x.Item1 == fileName);
			if (cachedModel == null || cachedModel.Item2 == null)
				return;

			if (_iPtrDigudaStone != null)
				return;

			_iPtrDigudaStone = Instantiate(cachedModel.Item2);
			_iPtrDigudaStone.SetActive(false);

			var scale = Vector3.one;
			var monsNo = Entity.GetSimpleParam().monsNo;
			if (monsNo == MonsNo.DAGUTORIO)
			{
				scale.x = DAGUTORIO_STONE_SIZE;
				scale.y = DAGUTORIO_STONE_SIZE;
				scale.z = DAGUTORIO_STONE_SIZE;
			}
			else if (monsNo == MonsNo.DHIGUDA)
			{
				scale.x = DHIGUDA_STONE_SIZE;
				scale.y = DHIGUDA_STONE_SIZE;
				scale.z = DHIGUDA_STONE_SIZE;
			}

			_iPtrDigudaStone.SetScaleOffset(scale);
		}
		public void SetVisibleTame(bool value) {
