		public void SetVisibleMigawari(bool value) {
			if (!IsEnable)
				return;

			if (!IsLoadedMigawari() && value)
				CreateMigawari();

			IsVisibleMigawari = value;
			UpdateVisible();
		}
		public bool IsLoadedMigawari() {
			return _iPtrMigawariObject != null;
		}
		private void CreateMigawari() {
			string fileName = "ob0301_00";
			var cachedModel = BattleViewAssetManager.CachedModelData.Find(x => x.Item1 == fileName);
			if (cachedModel == null || cachedModel.Item2 == null)
				return;

			if (IsLoadedMigawari())
				return;

			_iPtrMigawariObject = Instantiate(cachedModel.Item2);
			_iPtrMigawariObject.SetActive(false);
		}
